#include <bits/stdc++.h>

using namespace std;

int main() {
    // 入力
    int n;
    cin >> n;
    vector<string> s(n);
    vector<int> c(n);
    for (int i = 0; i < n; ++i) {
        cin >> s[i] >> c[i];
    }

    // 文字列の辞書順ソート
    sort(s.begin(), s.end());

    // 勝者の番号を求める
    int sum_rating = 0;
    for (const int e : c) {
        sum_rating += e;
    }
    const int winner = sum_rating % n;

    // 出力
    cout << s[winner] << endl;
}
